% no-anki
Valgono le seguenti proprietà:
\begin{itemize}
    \item Per l'intersezione:
    \begin{enumerate}
        \item $A \cap A = A$ (Idempotenza);
        \item $A \cap B = B \cap A$ (Commutatività);
        \item $(A \cap B) \cap C = A \cap (B \cap C)$ (Associatività).
    \end{enumerate}
    \item Per l'unione:
    \begin{enumerate}
        \item $A \cup A = A$ (Idempotenza);
        \item $A \cup B = B \cup A$ (Commutatività);
        \item $(A \cup B) \cup C = A \cup (B \cup C)$ (Associatività).
    \end{enumerate}
\end{itemize}

Siano $f: A \to B$ e $g: B \to C$ funzioni. Valgono le seguenti proposizioni:
\begin{enumerate}
    \item Se $f$ e $g$ sono suriettive, allora $g \circ f$ è suriettiva;
    \item Se $f$ e $g$ sono iniettive, allora $g \circ f$ è iniettiva;
    \item Se $f$ e $g$ sono biettive, allora $g \circ f$ è biettiva.
\end{enumerate}

Sia $f: A \to B$ una funzione. Si ha:
\begin{enumerate}
    \item $id_B \circ f = f$;
    \item $f \circ id_A = f$.
\end{enumerate}

L'insieme $U(S)$ è chiuso rispetto all'operazione $\omega$ e all'inversione:
\begin{enumerate}
    \item Se $a, b \in U(S)$, allora $a \omega b \in U(S)$, con $(a \omega b)^{-1} = b^{-1} \omega a^{-1}$.
    \item Se $a \in U(S)$, allora $a^{-1} \in U(S)$, con $(a^{-1})^{-1} = a$.
\end{enumerate}

Sia $(G, \cdot)$ un gruppo e $H \subseteq G$ un sottoinsieme non vuoto. $H$ è un \textbf{sottogruppo} di $G$, denotato con $H \le G$, se verifica le seguenti condizioni:
\begin{enumerate}
    \item Chiusura rispetto all'operazione: $\forall x, y \in H \implies x \cdot y \in H$;
    \item Chiusura rispetto all'inverso: $\forall x \in H \implies x^{-1} \in H$.
\end{enumerate}

Sia $H \le G$. Si ha:
\begin{enumerate}
    \item $1_H = 1_G$;
    \item L'inverso di ogni elemento in $H$ coincide con il suo inverso in $G$.
\end{enumerate}

L'insieme dei numeri naturali $\mathbb{N}$ è definito dal seguente sistema assiomatico (Assiomi di Peano):
\begin{enumerate}
    \item \textit{Esistenza dello zero}: $0 \in \mathbb{N}$;
    \item \textit{Esistenza del successivo}: Esiste una funzione $\sigma: \mathbb{N} \to \mathbb{N}$ detta funzione successivo.
    \item \textit{Iniettività}: La funzione $\sigma$ è iniettiva:
    \[ \forall n, m \in \mathbb{N}, \ \sigma(n) = \sigma(m) \implies n = m \]
    \item \textit{Elemento minimo}: $0 \notin \sigma(\mathbb{N})$, ovvero $\nexists n \in \mathbb{N} : \sigma(n) = 0$;
    \item \textit{Principio di Induzione}: Se un sottoinsieme $A \subseteq \mathbb{N}$ soddisfa $0 \in A$ e $\sigma(A) \subseteq A$, allora $A = \mathbb{N}$. In simboli:
    \[ (0 \in A \ \land \ \sigma(A) \subseteq A) \implies A = \mathbb{N} .\]
\end{enumerate}

Fissato $a \in \mathbb{N}$, l'applicazione \textbf{traslazione} $T_a : \mathbb{N} \to \mathbb{N}$ è definita per induzione da:
\begin{enumerate}
    \item $T_a(0) = a$;
    \item $T_a(\sigma(x)) = \sigma(T_a(x))$.
\end{enumerate}

Dati $a, b \in \mathbb{N}$, l'\textbf{addizione} è definita ponendo:
\[ a + b := T_a(b) \]
Dalle proprietà della traslazione derivano le relazioni:
\begin{enumerate}
    \item $a + 0 = a$;
    \item $a + \sigma(b) = \sigma(a+b)$.
\end{enumerate}

Sia $(A, +)$ un monoide. Per ogni $a, b \in A$ e $r, s, m \in \mathbb{N}$ si ha:
\begin{enumerate}
    \item $r \cdot a + s \cdot a = (r+s) \cdot a$;
    \item Se $A$ è commutativo, $m \cdot (a+b) = m \cdot a + m \cdot b$.
\end{enumerate}

Per ogni $r \in \mathbb{N}$ si ha:
\begin{enumerate}
    \item $r \cdot 0 = 0$;
    \item $r \cdot 1 = r$.
\end{enumerate}

Una relazione $R$ può possedere le seguenti proprietà:
\begin{itemize}
    \item \textit{Riflessiva}: $\forall a \in X, \ aRa$;
    \item \textit{Antiriflessiva}: $\forall a \in X, \ (a,a) \notin R$;
    \item \textit{Transitiva}: $\forall a,b,c \in X$, $aRb \land bRc \implies aRc$;
    \item \textit{Simmetrica}: $\forall a,b \in X$, $aRb \implies bRa$;
    \item \textit{Antisimmetrica}: $\forall a,b \in X$, $aRb \land bRa \implies a=b$.
\end{itemize}

\begin{enumerate}
    \item \textit{Relazione d'Ordine}: Riflessiva, Transitiva, Antisimmetrica.
    \item \textit{Relazione di Equivalenza}: Riflessiva, Transitiva, Simmetrica.
\end{enumerate}

Un insieme non vuoto $A$ dotato di due operazioni binarie interne, $+$ (addizione) e $\cdot$ (moltiplicazione), si definisce \textbf{anello} e si denota con $(A, +, \cdot)$, se verifica le seguenti condizioni:
\begin{enumerate}
    \item $(A, +)$ è un gruppo abeliano;
    \item $(A, \cdot)$ è un semigruppo;
    \item Valgono le leggi distributive (sinistra e destra) della moltiplicazione rispetto all'addizione:
    \[ a \cdot (b+c) = a \cdot b + a \cdot c \quad \text{e} \quad (a+b) \cdot c = a \cdot c + b \cdot c \quad \forall a,b,c \in A .\]
\end{enumerate}

Sia $(S, *)$ una struttura algebrica e $R$ una relazione di equivalenza compatibile con $*$. Valgono le seguenti proprietà nell'insieme quoziente $S/R$:
\begin{enumerate}
    \item Se $*$ è commutativa in $S$, l'operazione indotta $*$ è commutativa in $S/R$;
    \item Se $*$ è associativa in $S$, l'operazione indotta $*$ è associativa in $S/R$;
    \item Se $1_S$ è elemento neutro in $S$, la classe $[1_S]_R$ è elemento neutro in $S/R$.
\end{enumerate}

L'applicazione $j$ è un omomorfismo iniettivo di monoidi (rispetto a somma e prodotto):
\begin{enumerate}
    \item $j(x+y) = j(x) + j(y)$ per ogni $x,y \in \mathbb{N}$;
    \item $j(x \cdot y) = j(x) \cdot j(y)$ per ogni $x,y \in \mathbb{N}$;
    \item $j$ è iniettiva.
\end{enumerate}

Per ogni $z_1, z_2 \in \mathbb{Z}$ valgono le seguenti proprietà:
\begin{itemize}
    \item \textit{Moltiplicatività:} $|z_1 \cdot z_2| = |z_1| \cdot |z_2|$;
    \item \textit{Disuguaglianza Triangolare:} $|z_1 + z_2| \le |z_1| + |z_2|$.
\end{itemize}

Per ogni $a, b, c \in \mathbb{Z}$ valgono le seguenti proprietà:
\begin{itemize}
    \item \textit{Riflessività:} $a \mid a$;
    \item \textit{Transitività:} $a \mid b \land b \mid c \implies a \mid c$;
    \item \textit{Divisore Universale:} $1 \mid a$;
    \item \textit{Divisori dell'Unità (Unità di $\mathbb{Z}$):} $a \mid 1 \iff a=1 \lor a=-1$ (ossia $U(\mathbb{Z}) = \{1, -1\}$);
    \item \textit{Antisimmetria (a meno del segno):} $a \mid b \land b \mid a \iff a = b \lor a = -b$.
\end{itemize}

Siano $a,b \in \mathbb{Z}$. Un intero $d \in \mathbb{Z}$ si dice un \textbf{massimo comun divisore} di $a$ e $b$, e si denota con $d = \operatorname{MCD}(a,b)$, se soddisfa:
\begin{enumerate}
    \item $d \mid a$ e $d \mid b$;
    \item $\forall c \in \mathbb{Z}$, se $c \mid a$ e $c \mid b$, allora $c \mid d$.
\end{enumerate}

Sia $p \in \mathbb{Z}$ con $p > 1$. Le seguenti asserzioni sono equivalenti:
\begin{enumerate}
    \item $p$ è un numero primo;
    \item L'anello quoziente $(\mathbb{Z}_p, +, \cdot)$ è un \textbf{campo};
    \item L'anello quoziente $(\mathbb{Z}_p, +, \cdot)$ è un \textbf{dominio d'integrità}.
\end{enumerate}

Sia data l'equazione lineare $\bar{a}x = \bar{b}$ in $\mathbb{Z}_n$ e sia $d = \operatorname{MCD}(a,n) \ge 1$.
\begin{enumerate}
    \item L'equazione ammette soluzioni in $\mathbb{Z}_n$ se e solo se $d \mid b$.
    \item In caso affermativo, l'equazione ammette esattamente $d$ soluzioni distinte in $\mathbb{Z}_n$. Nota una soluzione particolare $\overline{s_0}$, tutte le soluzioni sono date da:
    \[ \overline{s_t} = \overline{s_0 + \frac{n}{d}t} \qquad \text{al variare di } t \in \{0, 1, \dots, d-1\} .\]
\end{enumerate}

Sia $(G, \cdot)$ un gruppo e $x \in G$. Valgono le seguenti asserzioni:
\begin{enumerate}
    \item $\langle x \rangle \le G$;
    \item Per ogni sottogruppo $H \le G$, $\langle x \rangle \le H \iff x \in H$.
\end{enumerate}

Sia $(G, \cdot)$ un gruppo e $x \in G$.
\begin{itemize}
    \item L'elemento $x$ è \textbf{periodico} se esiste $t \in \mathbb{Z}^*$ tale che $x^t = 1_G$. Posto $E(x) = \{s \in \mathbb{Z}^* \mid x^s = 1_G\}$, il \textbf{Periodo di $x$}, denotato con $o(x)$, è definito come $\min E(x)$.
    \item L'elemento $x$ è \textbf{aperiodico} se $x^s \neq 1_G$ per ogni $s \in \mathbb{Z}^*$.
\end{itemize}

Sia $(G, \cdot)$ un gruppo e $x \in G$.
\begin{enumerate}
    \item Se $x$ è aperiodico, si ha $x^s = x^t \iff s = t$. Il sottogruppo $\langle x \rangle$ ha cardinalità infinita.
    \item Se $x$ è periodico di periodo $m$, si ha $x^s = x^t \iff s \equiv_m t$. L'ordine di $\langle x \rangle$ è $m$ e risulta $\langle x \rangle = \{1_G, x, x^2, \dots, x^{m-1}\}$.
\end{enumerate}

La funzione indicatrice di Eulero soddisfa le seguenti proprietà:
\begin{enumerate}
    \item Se $p$ è un numero primo, $\varphi(p) = p - 1$.
    \item Se $p$ è un numero primo e $\alpha \ge 1$ è un intero, $\varphi(p^\alpha) = p^{\alpha-1}(p - 1)$.
    \item È moltiplicativa: se $1 = \operatorname{MCD}(n, m)$, allora $\varphi(n \cdot m) = \varphi(n) \cdot \varphi(m)$.
\end{enumerate}

Sia $\alpha \in S_n$. Si definiscono:
\begin{itemize}
    \item Il \textbf{Supporto} di $\alpha$: $\operatorname{Supp}(\alpha) = \{ x \in X \mid \alpha(x) \neq x \}$.
    \item L'\textbf{Insieme dei punti fissi} di $\alpha$: $F(\alpha) = \{ x \in X \mid \alpha(x) = x \}$.
\end{itemize}
Tali insiemi costituiscono una partizione di $X$.

Siano $\alpha, \beta \in S(X)$ due permutazioni disgiunte. Si ha:
\begin{enumerate}
    \item \textbf{Commutatività}: $\alpha \circ \beta = \beta \circ \alpha$.
    \item \textbf{Indipendenza}: $\alpha \circ \beta = id_X \iff \alpha = id_X \land \beta = id_X$.
    \item \textbf{Periodo}: Se periodiche, $o(\alpha \circ \beta) = \operatorname{mcm}(o(\alpha), o(\beta))$.
\end{enumerate}

Sia $(G, \cdot)$ un gruppo e sia $X$ un insieme non vuoto. Un'azione di $G$ su $X$ è un'applicazione
\[ G \times X \to X, \quad (g, x) \mapsto g \cdot x \]
tale che siano soddisfatti i seguenti assiomi per ogni $x \in X$ e per ogni $g_1, g_2 \in G$:
\begin{enumerate}
    \item \textit{Proprietà neutra}: $1_G \cdot x = x$;
    \item \textit{Proprietà associativa}: $(g_1 g_2) \cdot x = g_1 \cdot (g_2 \cdot x)$.
\end{enumerate}

Sia $f: G \to G'$ un omomorfismo. Si ha:
\begin{enumerate}
    \item $f(1_G) = 1_{G'}$;
    \item $f(x^{-1}) = f(x)^{-1} \quad \forall x \in G$;
    \item $f(x^n) = f(x)^n \quad \forall x \in G, \forall n \in \mathbb{Z}$.
\end{enumerate}

Sia $f: G \to G'$ un omomorfismo e $H \le G$. Posto $f(H) = \{f(x) \mid x \in H\}$, valgono:
\begin{enumerate}
    \item $f(H) \le G'$;
    \item Se $H$ è abeliano, $f(H)$ è abeliano;
    \item Se $H = \langle x \rangle$, $f(H) = \langle f(x) \rangle$;
    \item Se $a \in G$ è periodico, $f(a)$ è periodico e $o(f(a)) \mid o(a)$.
\end{enumerate}

Sia $G$ un gruppo e $g \in G$. Si definiscono:
\begin{itemize}
    \item \textbf{Moltiplicazione a sinistra}: $l_g(x) = gx$;
    \item \textbf{Moltiplicazione a destra}: $\rho_g(x) = xg$.
\end{itemize}

Siano $G$ un gruppo e $N \le G$. Sono equivalenti:
\begin{enumerate}
    \item $N \trianglelefteq G$;
    \item $N$ è invariante per coniugio: $gNg^{-1} = N \ \forall g \in G$;
    \item $N$ contiene ogni suo coniugato: $gNg^{-1} \subseteq N \ \forall g \in G$.
\end{enumerate}

Sia $f: R \to S$ omomorfismo con $f \neq 0$. Si ha:
\begin{enumerate}
    \item $f(R)$ è sottoanello di $S$;
    \item Se $R$ commutativo, $f(R)$ commutativo;
    \item Se $R$ unitario, $f(R)$ unitario con $1_{f(R)} = f(1_R)$;
    \item Se $R$ unitario e $x \in R$ invertibile, $f(x)$ invertibile con $f(x^{-1}) = f(x)^{-1}$;
    \item Se $R$ dominio d'integrità ed $f$ iniettiva, $f(R)$ dominio d'integrità;
    \item Se $R$ campo ed $f$ iniettiva, $f(R)$ campo.
\end{enumerate}

Sia $f: R \rightarrow S$ un isomorfismo di anelli. Si ha:
\begin{enumerate}
    \item $R$ è commutativo $\iff S$ è commutativo;
    \item $R$ è unitario $\iff S$ è unitario;
    \item $x \in U(R) \iff f(x) \in U(S)$;
    \item $R$ è dominio d'integrità $\iff S$ è dominio d'integrità;
    \item $R$ è campo $\iff S$ è campo.
\end{enumerate}

Sia $(A,+,\cdot)$ un anello. Un sottoinsieme $I \subseteq A$ è un \textbf{ideale bilatero} di $A$ se e solo se:
\begin{enumerate}
    \item $I \le (A,+)$;
    \item $\forall a \in I, \forall x \in A$, si ha $a \cdot x \in I$ e $x \cdot a \in I$.
\end{enumerate}
Se vale esclusivamente $a \cdot x \in I$, $I$ si dice ideale destro; se vale esclusivamente $x \cdot a \in I$, $I$ si dice ideale sinistro.

Sia $I$ un ideale bilatero dell'anello $A$. La congruenza modulo $I$ è una relazione di equivalenza compatibile con le operazioni di $A$. Per ogni $a \equiv \alpha \pmod I$ e $b \equiv \beta \pmod I$:
\begin{enumerate}
    \item $(a+b) \equiv (\alpha+\beta) \pmod I$
    \item $a \cdot b \equiv \alpha \cdot \beta \pmod I$
\end{enumerate}

Sia $A$ un anello e $R$ una relazione di equivalenza su $A$. Sono equivalenti:
\begin{enumerate}
    \item $R$ è compatibile con le operazioni di $A$;
    \item Esiste un epimorfismo di anelli $f$ da $A$ tale che $R = R_f$ (con $a \mathrel{R_f} \alpha \iff f(a) = f(\alpha)$);
    \item Esiste un omomorfismo di anelli $f$ da $A$ tale che $R = R_f$;
    \item Esiste un omomorfismo di anelli $f$ da $A$ tale che $R$ coincide con la congruenza $\pmod{\ker f}$;
    \item Esiste un ideale bilatero $I$ di $A$ tale che $R$ coincide con la congruenza $\pmod I$.
\end{enumerate}

Dato $z = a+bi \in \mathbb{C}$, si definisce:
\begin{itemize}
    \item \textbf{Coniugato di $z$}: $\overline{z} = a-bi$. Geometricamente rappresenta il punto simmetrico rispetto all'asse $x$. In forma matriciale corrisponde alla trasposta: $\overline{a+bi} = \begin{pmatrix} a & -b \\ b & a \end{pmatrix} = \begin{pmatrix} a & b \\ -b & a \end{pmatrix}^t$.
    \item \textbf{Norma di $z$}: $N(z) = a^2+b^2$. Corrisponde al determinante della rappresentazione matriciale.
    \item \textbf{Modulo di $z$}: $|z| = \sqrt{N(z)} = \sqrt{a^2+b^2}$. Indica la distanza dall'origine, con $|z| \ge 0$.
\end{itemize}

Per ogni $z, w \in \mathbb{Z}[i]$ con $w \neq 0$, esistono $q, r \in \mathbb{Z}[i]$ tali che:
\begin{enumerate}
    \item $z = wq + r$
    \item $r = 0$ oppure $N(r) < N(w)$
\end{enumerate}

Sia $A$ un dominio d'integrità. Si dice che $A$ è un \textbf{Dominio Euclideo} se esiste una valutazione $v: A^* \rightarrow \mathbb{N}$ tale che:
\begin{enumerate}
    \item $v(ab) \ge v(a)$ per ogni $a,b \in A^*$.
    \item Per ogni $a,b \in A$ con $b \neq 0$, esistono $q,r \in A$ tali che $a = bq+r$ con $r=0$ oppure $v(r) < v(b)$.
\end{enumerate}

Valgono le seguenti proprietà:
\begin{enumerate}
    \item $a \mid a$ per ogni $a \in A$.
    \item Se $a \mid b$ e $b \mid c$, allora $a \mid c$.
    \item $a \mid b$ e $b \mid a \iff \exists x \in U(A)$ tale che $a = bx$ ($a$ e $b$ associati).
\end{enumerate}

Siano $A$ un dominio d'integrità e $a,b \in A$. Un elemento $d \in A$ è $\text{MCD}(a,b)$ se:
\begin{enumerate}
    \item $d \mid a$ e $d \mid b$.
    \item Per ogni $c \in A$ tale che $c \mid a$ e $c \mid b$, si ha $c \mid d$.
\end{enumerate}

Sia $A$ un dominio d'integrità. L'elemento $p \in A$ si dice \textbf{irriducibile} in $A$ se:
\begin{enumerate}
    \item $p \neq 0_A$ e $p \notin U(A)$.
    \item L'insieme dei divisori di $p$ è $U(A) \cup pU(A)$.
\end{enumerate}

Un dominio d'integrità $A$ si dice \textbf{a fattorizzazione unica} (UFD) se per ogni $a \in A$ non nullo e non invertibile:
\begin{enumerate}
    \item \textbf{(Esistenza)} Esistono $n \ge 1$ e $p_1, \dots, p_n$ irriducibili in $A$ tali che $a = p_1 \dots p_n$.
    \item \textbf{(Unicità)} Se $a = p_1 \dots p_n = q_1 \dots q_m$ in irriducibili, allora $n=m$ e, a meno di riordinamenti, ogni $p_i$ è associato al corrispondente $q_i$.
\end{enumerate}

Sia $A$ un dominio d'integrità. L'elemento $p \in A$ si dice \textbf{primo} in $A$ se:
\begin{enumerate}
    \item $p \neq 0_A$ e $p \notin U(A)$.
    \item Per ogni $a,b \in A$, $p \mid ab \implies p \mid a$ oppure $p \mid b$.
\end{enumerate}

Siano $a, b \in A$ e $n, m \in \mathbb{N}$. In $A^{\mathbb{N}}$ vale:
\begin{enumerate}
    \item $aX^n + bX^n = (a+b)X^n$
    \item $aX^n \cdot bX^m = (ab)X^{n+m}$
\end{enumerate}

Siano $f, g \in A[X]^*$ polinomi non nulli. Valgono le relazioni:
\begin{enumerate}
    \item $\operatorname{gr}(-f) = \operatorname{gr} f$
    \item Se $f+g \neq 0$, allora $\operatorname{gr}(f+g) \leq \max \{\operatorname{gr} f, \operatorname{gr} g\}$
    \item Se $f \cdot g \neq 0$, allora $\operatorname{gr}(f \cdot g) \leq \operatorname{gr} f + \operatorname{gr} g$
\end{enumerate}

Sia $K$ campo algebricamente chiuso. Si ha:
\begin{enumerate}
    \item Ogni polinomio irriducibile in $K[X]$ ha grado 1.
    \item Ogni polinomio di grado $n \ge 1$ si scompone in $n$ fattori lineari.
\end{enumerate}

Per $z$ algebrico su $K$ e $p \in K[X]$, sono equivalenti:
\begin{enumerate}
    \item $\ker \varphi_z = (p)$.
    \item $p$ monico con $p(z)=0$ e grado minimo.
    \item $p$ con $p(z)=0$ ed è irriducibile in $K[X]$.
\end{enumerate}

Sia $f \in K[X]$ non nullo di grado $n \ge 1$. Esiste un'estensione $F$ di $K$ e $z \in F$ tali che:
\begin{enumerate}
    \item $f(z) = 0$.
    \item $F = K(z)$.
    \item $[K(z) : K] \le n$.
\end{enumerate}

La relazione $\leq$ è una relazione d'ordine totale su $\mathbb{R}$. Essa soddisfa le seguenti proprietà:
    \begin{itemize}
        \item[$a$] \textit{Riflessività}: per ogni $a\in\mathbb{R}, \quad a\leq a$;
        \item[$b$] \textit{Antisimmetria}: per ogni $a,b\in\mathbb{R}, \quad a\leq b \;\land\; b\leq a \implies a=b$;
        \item[$c$] \textit{Transitività}: per ogni $a,b,c\in\mathbb{R}, \quad a\leq b \;\land\; b\leq c \implies a\leq c$;
        \item[$d$] \textit{Totalità}: per ogni $a,b\in\mathbb{R}, \quad a\leq b \;\lor\; b\leq a$.
    \end{itemize}
    La relazione $<$ soddisfa le seguenti proprietà di compatibilità con le operazioni:
    \begin{itemize}
        \item[$e$] \textit{Monotonia rispetto alla somma}: per ogni $a,b,c\in\mathbb{R}, \quad a<b \implies a+c<b+c$;
        \item[$f$] \textit{Monotonia rispetto al prodotto}: per ogni $a,b,c\in\mathbb{R}, \quad a<b \;\land\; c\in\mathbb{R}^+ \implies ca<cb$.
    \end{itemize}

Per ogni numero reale valgono le seguenti proprietà:
    \begin{enumerate}
        \item $-b\cdot a=-(b\cdot a)$;
        \item $-1\cdot a=-a$;
        \item L'opposto dell'opposto di $a$ è $a$, cioè $-(-a)=a$;
        \item Il reciproco del reciproco di $a$ (con $a \neq 0$) è $a$, cioè $\dfrac{1}{\frac{1}{a}}=a$;
        \item Se un numero è positivo, il suo opposto è negativo;
        \item Somma membro a membro: per ogni $a,b,c,d \in \mathbb{R}$, 
        \[a<c \quad \text{e} \quad b<d \implies a+b<c+d.\]
    \end{enumerate}

Siano $A\subseteq\mathbb{R}$ e $m\in\mathbb{R}$.
    Diciamo che $m$:
    \begin{itemize}
        \item è un \textbf{maggiorante} per $A$ se, per ogni $x \in A$, si ha $x \leq m$;
        \item è un \textbf{minorante} per $A$ se, per ogni $x \in A$, si ha $x \geq m$;
        \item è il \textbf{massimo} per $A$ se $m$ è un maggiorante per $A$ e contemporaneamente $m \in A$;
        \item è il \textbf{minimo} per $A$ se $m$ è un minorante per $A$ e contemporaneamente $m \in A$.
    \end{itemize}

Sia $m\in\mathbb{R}$. Allora:
    \begin{itemize}
        \item $m$ è un maggiorante per l'insieme vuoto $\emptyset$;
        \item $m$ non è un maggiorante per un insieme $A\subseteq\mathbb{R}$ se e solo se esiste almeno un $x\in A$ tale che $x>m$.
    \end{itemize}

Sia $A \subseteq \mathbb{R}$.
    \begin{itemize}
        \item Chiamiamo \textbf{estremo superiore} di $A$ il minimo del complesso dei maggioranti (cioè $\min A^\leq$). Se esiste, è unico e si indica con $\sup A$.
        \item Chiamiamo \textbf{estremo inferiore} di $A$ il massimo del complesso dei minoranti (cioè $\max A^\geq$). Se esiste, è unico e si indica con $\inf A$.
    \end{itemize}

Sia $A\subseteq\mathbb{R}$.
    \begin{enumerate}
        \item Se esiste $m=\max A$, allora $m=\sup A$.
        \item Se esiste $s=\min A$, allora $s=\inf A$.
    \end{enumerate}

Siano $A\subseteq\mathbb{R}$ e $m\in\mathbb{R}$. 
    Le seguenti due affermazioni sono equivalenti:
    \begin{enumerate}
        \item[($a$)] $m=\sup A$;
        \item[($b$)] valgono contemporaneamente le seguenti due proprietà:
        \begin{enumerate}
            \item per ogni $x\in A$, si ha $x\leq m$ (cioè $m$ è un maggiorante);
            \item per ogni $\varepsilon > 0$, esiste $x\in A$ tale che $x>m-\varepsilon$.
        \end{enumerate}
    \end{enumerate}

Sia $A\subseteq\mathbb{R}$. Diciamo che l'insieme $A$ è:
    \begin{itemize}
        \item \textbf{Limitato superiormente} se $A^{\leq}\neq \emptyset$;
        \item \textbf{Limitato inferiormente} se $A^{\geq}\neq \emptyset$;
        \item \textbf{Illimitato superiormente} se $A^{\leq}=\emptyset$;
        \item \textbf{Illimitato inferiormente} se $A^{\geq}=\emptyset$;
        \item \textbf{Limitato} se è limitato sia superiormente che inferiormente;
        \item \textbf{Illimitato} se è illimitato sia superiormente che inferiormente.
    \end{itemize}

Con \textbf{insieme dei reali estesi} identifichiamo l'insieme:
    \[ \overline{\mathbb{R}}=\mathbb{R}\cup\{-\infty,+\infty\} \]
    Sia $a\in \mathbb{R}$. Definiamo formalmente le seguenti proprietà:
    \begin{enumerate}
        \item $-\infty < a < +\infty$;
        \item $-\infty+a = -\infty-\infty = -\infty \quad \text{e} \quad +\infty-a = +\infty+\infty = +\infty$;
        \item per ogni $a>0, \quad a\cdot(+\infty)=+\infty \quad \text{e} \quad a\cdot(-\infty)=-\infty$;
        \item per ogni $a<0, \quad a\cdot(+\infty)=-\infty \quad \text{e} \quad a\cdot(-\infty)=+\infty$;
        \item $\dfrac{a}{+\infty}=\dfrac{a}{-\infty}=0$.
    \end{enumerate}

Un insieme $I\subseteq\mathbb{R}$ si dice \textbf{induttivo} se soddisfa le seguenti due proprietà:
    \begin{enumerate}
        \item $1\in I$;
        \item per ogni $x\in I$, si ha che $x+1\in I$.
    \end{enumerate}
    La collezione di tutti gli insiemi induttivi viene indicata con $\mathcal{J}$.

Dovendo definire una sequenza di enti $E_n$ per ogni $n\in\mathbb{N}$, è sufficiente procedere nel seguente modo:
    \begin{enumerate}
        \item Definire esplicitamente il caso base $E_1$;
        \item Stabilire una regola che permetta di costruire $E_{n+1}$ a partire da $E_n$, per ogni $n\in\mathbb{N}$.
    \end{enumerate}

Siano $a\in\mathbb{R}$ e $n\in\mathbb{N}$. La potenza $a^n$ è definita ricorsivamente dalle seguenti condizioni:
    \begin{enumerate}
        \item $a^1=a$;
        \item per ogni $n\in\mathbb{N}, \; a^{n+1}=a^n\cdot a$.
    \end{enumerate}

Siano $a_1,a_2,\dots,a_n$ una sequenza di $n$ numeri reali. La loro somma $a_1+a_2+\dots+a_n$ si può indicare in forma compatta con il simbolo di \textit{sommatoria}:
    \[\sum_{i=1}^{n}a_i\]
    che si legge "sommatoria per $i$ che va da $1$ a $n$ di $a_i$". Il simbolo $i$ prende il nome di \textit{indice di sommatoria}. 
    Essa è definita ricorsivamente dalle seguenti condizioni:
    \begin{enumerate}
        \item $\displaystyle \sum_{i=1}^{1}a_i = a_1$;
        \item $\displaystyle \sum_{i=1}^{n+1}a_i = \sum_{i=1}^{n}a_i + a_{n+1}$.
    \end{enumerate}

Si chiama $n$ \textit{fattoriale}, e si indica con il simbolo $n!$, il prodotto dei primi $n$ numeri naturali consecutivi:
    \[n! = 1\cdot 2\cdot \dots \cdot(n-1)\cdot n.\]
    Esso è definito ricorsivamente dalle seguenti condizioni:
    \begin{enumerate}
        \item $1! = 1$;
        \item $n! = n \cdot (n-1)!$.
    \end{enumerate}

Sia $f:A\to\mathbb{R}$. Si definiscono i seguenti valori (se esistono):
    \begin{itemize}
        \item \textbf{Estremo superiore}: $\sup f(A)$;
        \item \textbf{Estremo inferiore}: $\inf f(A)$;
        \item \textbf{Massimo}: $\max f(A)$;
        \item \textbf{Minimo}: $\min f(A)$.
    \end{itemize}

Sia $f:A\to\mathbb{R}$. Per ogni coppia di punti $x_1, x_2 \in A$ con $x_1 < x_2$, diciamo che $f$ è: 
    \begin{itemize}
        \item \textbf{crescente}: se \(f(x_1) \leq f(x_2);\)
        \item \textbf{strettamente crescente}: se \(f(x_1) < f(x_2);\)
        \item \textbf{decrescente}: se \(f(x_1) \geq f(x_2);\)
        \item \textbf{strettamente decrescente}: se \(f(x_1) > f(x_2).\)
    \end{itemize}
    In generale, la funzione $f$ si dice:
    \begin{itemize}
        \item \textbf{monotòna} se è crescente oppure decrescente;
        \item \textbf{strettamente monotòna} se è strettamente crescente oppure strettamente decrescente.
    \end{itemize}

\begin{itemize}
        \item[($a$)] Ogni funzione strettamente monotòna è invertibile.
        \item[($b$)] La sua inversa è anch'essa strettamente monotòna e conserva lo stesso tipo di monotònia.
    \end{itemize}

Sia $f:A\to\mathbb{R}$. Per ogni coppia di punti $x_1, x_2 \in A$ con $x_1 < x_2$, diciamo che $f$ è: 
    \begin{itemize}
        \item \textbf{crescente}: se \(f(x_1) \leq f(x_2);\)
        \item \textbf{strettamente crescente}: se \(f(x_1) < f(x_2);\)
        \item \textbf{decrescente}: se \(f(x_1) \geq f(x_2);\)
        \item \textbf{strettamente decrescente}: se \(f(x_1) > f(x_2).\)
    \end{itemize}
    In generale, la funzione $f$ si dice:
    \begin{itemize}
        \item \textbf{monotòna} se è crescente oppure decrescente;
        \item \textbf{strettamente monotòna} se è strettamente crescente oppure strettamente decrescente.
    \end{itemize}

\begin{itemize}
        \item[($a$)] Ogni funzione strettamente monotòna è invertibile.
        \item[($b$)] La sua inversa è anch'essa strettamente monotòna e conserva lo stesso tipo di monotònia.
    \end{itemize}

Per una funzione $f:A\to\mathbb{R}$ sono equivalenti le seguenti tre affermazioni:
    \begin{enumerate}
        \item $f$ è monotòna;
        \item Dati $p,q,r\in A$ con $p<q<r$, si ha che $f(q)$ è compreso tra $f(p)$ e $f(r)$;
        \item Dati $p,r\in A$ con $p<r$, la restrizione di $f$ all'intervallo $[p,r]\cap A$ assume in $p$ e in $r$ un punto di massimo e un punto di minimo. 
    \end{enumerate}

